import 'package:flutter/material.dart';import '../services/global_tours_service.dart';
class OperationsScreen extends StatefulWidget{const OperationsScreen({super.key,required this.user});final Map<String,dynamic> user;@override State<OperationsScreen> createState()=>_OperationsScreenState();}
class _OperationsScreenState extends State<OperationsScreen>{final s=GlobalToursService();List<Map<String,dynamic>> b=[];bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{b=await s.rawList('bookings','${widget.user['tenantId']??''}');if(mounted)setState(()=>loading=false);}Future<void> status(String id,String v)async{await s.setBookingStatus(id,'${widget.user['tenantId']}',v);await load();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Travel Operations')),body:loading?const Center(child:CircularProgressIndicator()):ListView.builder(itemCount:b.length,itemBuilder:(c,i){final x=b[i];return Card(margin:const EdgeInsets.all(8),child:ListTile(title:Text('${x['tourName']??x['tourId']??'Booking'}'),subtitle:Text('Guests: ${x['numberOfGuests']??0} • ${x['status']??'pending'}'),trailing:PopupMenuButton<String>(onSelected:(v)=>status('${x['id']}',v),itemBuilder:(_)=>const[PopupMenuItem(value:'pending',child:Text('Pending')),PopupMenuItem(value:'confirmed',child:Text('Confirm')),PopupMenuItem(value:'cancelled',child:Text('Cancel')),PopupMenuItem(value:'completed',child:Text('Complete'))])));}));}}
